void run(torch::Tensor x, torch::Tensor op1_weight, torch::Tensor op2_weight, torch::Tensor op3_weight, torch::Tensor op4_weight, torch::Tensor output) {
    cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();
    (void)stream;

    auto op1 = at::linear(x, op1_weight);
    auto op2 = at::linear(op1, op2_weight);
    auto op3 = at::linear(op2, op3_weight);
    auto op4 = at::linear(op3, op4_weight);
    output.copy_(op4);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("run", &run, "torch linear kernel");
}
